"""Types for contract fenon.hand_pose.video 1.1.0 (row schema), generated by scripts/generate_types.py. Do not edit."""

from __future__ import annotations

from typing import Annotated, Literal

from pydantic import BaseModel, ConfigDict, Field
from typing_extensions import TypeAliasType


class ImageSize(BaseModel):
    model_config = ConfigDict(
        extra="ignore",
    )
    width: int = Field(..., ge=1)
    height: int = Field(..., ge=1)


ProjectedPoint2 = TypeAliasType(
    "ProjectedPoint2",
    Annotated[
        list[float],
        Field(
            ...,
            description="[x, y], or [null, null] when the joint can't be projected (z <= 1e-6).",
            max_length=2,
            min_length=2,
            title="ProjectedPoint2",
        ),
    ],
)


MissingPoint2 = TypeAliasType(
    "MissingPoint2",
    Annotated[
        list[None],
        Field(
            ...,
            description="[x, y], or [null, null] when the joint can't be projected (z <= 1e-6).",
            max_length=2,
            min_length=2,
            title="MissingPoint2",
        ),
    ],
)


Point2 = TypeAliasType(
    "Point2",
    Annotated[
        ProjectedPoint2 | MissingPoint2,
        Field(
            ...,
            description="[x, y], or [null, null] when the joint can't be projected (z <= 1e-6).",
            title="Point2",
        ),
    ],
)


Point3 = TypeAliasType(
    "Point3",
    Annotated[list[float], Field(..., max_length=3, min_length=3, title="Point3")],
)


Box = TypeAliasType(
    "Box",
    Annotated[
        list[float],
        Field(
            ...,
            description="Box around the projectable joints in pixels, or four nulls when none are projectable.",
            max_length=4,
            min_length=4,
            title="Box",
        ),
    ],
)


MissingBox = TypeAliasType(
    "MissingBox",
    Annotated[
        list[None],
        Field(
            ...,
            description="Box around the projectable joints in pixels, or four nulls when none are projectable.",
            max_length=4,
            min_length=4,
            title="MissingBox",
        ),
    ],
)


JointConfidenceItem = TypeAliasType(
    "JointConfidenceItem", Annotated[float | None, Field(..., ge=0.0, le=1.0)]
)


class Hand(BaseModel):
    model_config = ConfigDict(
        extra="ignore",
    )
    handedness: Literal["left", "right"]
    pixel_landmarks: list[Point2] = Field(
        ...,
        description="Pixels, origin top-left, x right, y down.",
        max_length=21,
        min_length=21,
    )
    normalized_landmarks: list[Point2] = Field(
        ...,
        description="pixel_landmarks divided by image width and height.",
        max_length=21,
        min_length=21,
    )
    landmarks_3d_camera: list[Point3] = Field(
        ...,
        description="Metres, camera frame: origin at the optical centre, x right, y down, z forward. Depth is scale-consistent, not metric.",
        max_length=21,
        min_length=21,
    )
    bbox_xyxy: Box | MissingBox = Field(
        ...,
        description="Box around the projectable joints in pixels, or four nulls when none are projectable.",
    )
    joint_state: list[Literal["in_frame_predicted", "outside_frame_predicted"]] = Field(
        ..., max_length=21, min_length=21
    )
    joint_confidence: list[JointConfidenceItem] = Field(
        ...,
        description="Always null for fenon/hand-pose-hm.",
        max_length=21,
        min_length=21,
    )
    hand_score: float | None = Field(..., description="Always null for fenon/hand-pose-hm.", ge=0.0, le=1.0)


class HandPoseFrame(BaseModel):
    model_config = ConfigDict(
        extra="ignore",
    )
    frame_index: int = Field(..., ge=0)
    timestamp_sec: float = Field(..., description="frame_index / fps.", ge=0.0)
    image_size: ImageSize = Field(..., title="ImageSize")
    joint_order: Literal[
        "wrist,thumb_cmc,thumb_mcp,thumb_ip,thumb_tip,index_mcp,index_pip,index_dip,index_tip,middle_mcp,middle_pip,middle_dip,middle_tip,ring_mcp,ring_pip,ring_dip,ring_tip,pinky_mcp,pinky_pip,pinky_dip,pinky_tip"
    ]
    raw_hand_count: int = Field(..., ge=0)
    suppressed_duplicate_count: int = Field(..., ge=0)
    hands: list[Hand] = Field(
        ..., description="Hands kept after duplicate removal. Order is not significant."
    )
